namespace BlazorApp.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private int _nextId = 1;
    private readonly List<Notification> _notifications = new();
    private readonly Lock _lock = new();

    public NotificationService()
    {
        // Seed with initial fake data
        _notifications.AddRange(new[]
        {
            CreateNotification("Welcome to BlazorApp!"),
            CreateNotification("Your profile has been updated."),
            CreateNotification("New feature: dark mode is now available."),
        });
    }

    public Task<List<Notification>> GetNotificationsAsync()
    {
        lock (_lock)
        {
            return Task.FromResult(_notifications.ToList());
        }
    }

    public Task<List<Notification>> GetNotificationsSinceAsync(int lastSeenId)
    {
        lock (_lock)
        {
            var newer = _notifications.Where(n => n.Id > lastSeenId).ToList();
            return Task.FromResult(newer);
        }
    }

    /// <summary>
    /// Simulates new notifications arriving over time.
    /// Call this periodically to generate fake traffic.
    /// </summary>
    public Task GenerateRandomNotificationAsync()
    {
        string[] templates =
        [
            "Server backup completed successfully.",
            "A new user signed up.",
            "Deployment to production finished.",
            "Disk usage is above 80%.",
            "Weekly report is ready for download.",
            "Scheduled maintenance starts in 1 hour.",
        ];

        var message = templates[Random.Shared.Next(templates.Length)];

        lock (_lock)
        {
            _notifications.Add(CreateNotification(message));
        }

        return Task.CompletedTask;
    }

    private Notification CreateNotification(string message)
    {
        return new Notification(_nextId++, message, DateTime.UtcNow);
    }
}

