    <p><em>Loading notifications...</em></p>
}
else if (notifications.Count == 0)
{
    <p>No notifications.</p>
}
else
{
    <ul class="list-group">
        @foreach (var n in notifications.OrderByDescending(x => x.Timestamp))
        {
            <li class="list-group-item d-flex justify-content-between align-items-start">
                <div>
                    <strong>@n.Message</strong>
                    <br />
                    <small class="text-muted">@n.Timestamp.ToString("g")</small>
                </div>
                <span class="badge bg-secondary rounded-pill">#@n.Id</span>
            </li>
        }
    </ul>
}

@code {
    private List<Notification>? notifications;
    private CancellationTokenSource? cts;

    [PersistentState]
    public List<Notification>? PersistedNotifications { get; set; }

    protected override async Task OnInitializedAsync()
    {
        if (PersistedNotifications is not null)
        {
            // Restored from prerender — skip the fetch
            notifications = PersistedNotifications;
        }
        else
        {
            // First render (prerender pass) — load from service
            notifications = await NotificationService.GetNotificationsAsync();
            PersistedNotifications = notifications;
        }
    }

    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken cancellationToken)
    {
        // Periodically generate a fake notification, then fetch new ones
        while (!cancellationToken.IsCancellationRequested)
        {
            try
            {
                await Task.Delay(TimeSpan.FromSeconds(5), cancellationToken);

                // Simulate a new notification arriving on the server
                await NotificationService.GenerateRandomNotificationAsync();

                var lastId = notifications?.Count > 0
                    ? notifications.Max(n => n.Id)
                    : 0;

                var newer = await NotificationService.GetNotificationsSinceAsync(lastId);

                if (newer.Count > 0)
                {
                    notifications ??= new();
                    notifications.AddRange(newer);
                    await InvokeAsync(StateHasChanged);
                }
            }
            catch (OperationCanceledException)
            {
                break;
            }
        }
    }

    public async ValueTask DisposeAsync()
    {
        if (cts is not null)
        {
            await cts.CancelAsync();
            cts.Dispose();
        }
    }
}

